package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.New(0, 0)
var WsBranchTot decimal.Decimal = decimal.New(0, 0)
var WsGrandTot decimal.Decimal = decimal.New(0, 0)
var WsSkipped int64 = 0
var WsAmtEd string = ""
var WsBalEd string = ""
var WsTotEd string = ""

// current record
var curRec LedgerRec

// file handling
var scanner *bufio.Scanner
var ledgerFile *os.File

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func intPow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func storeFixed(v decimal.Decimal, intDigits, scale int) decimal.Decimal {
	v = v.Truncate(int32(scale))
	scaled := v.Shift(int32(scale))
	// scaled should be integer; use IntPart (fits int64 for these sizes)
	modVal := intPow10(intDigits + scale)
	// handle large scaled that may exceed int64? fallback to decimal mod
	// try decimal mod
	modDec := decimal.New(1, int32(intDigits+scale))
	// scaled % modDec with sign
	// shopspring decimal Mod works for positive divisor
	rem := scaled.Mod(modDec)
	// Mod for negative dividend in shopspring returns positive remainder; we need signed remainder
	// So adjust: if original scaled negative, remainder should be negative
	if scaled.IsNegative() && rem.IsPositive() && !rem.IsZero() {
		// rem was computed as positive modulo; convert to negative low-order
		// e.g., -1234 mod 1000 should be -234, but Mod gives 766
		// So we compute: rem = rem - mod
		rem = rem.Sub(modDec)
	}
	return rem.Shift(-int32(scale))
}

func storeS9_7V99(v decimal.Decimal) decimal.Decimal { return storeFixed(v, 7, 2) }
func storeS9_9V99(v decimal.Decimal) decimal.Decimal { return storeFixed(v, 9, 2) }

// formatting edited pictures
func formatEdited(value decimal.Decimal, pic string) string {
	hasSign := false
	signChar := ' '
	picRest := pic
	if len(pic) > 0 && (pic[0] == '-' || pic[0] == '+') {
		hasSign = true
		if value.IsNegative() {
			signChar = '-'
		} else {
			signChar = ' '
		}
		// for display of negative zero, treat as positive
		if value.IsZero() {
			signChar = ' '
		}
		picRest = pic[1:]
	}
	// split picRest into integer and fraction parts
	dotIdx := strings.Index(picRest, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picRest[:dotIdx]
		fracPic = picRest[dotIdx+1:]
	} else {
		intPic = picRest
		fracPic = ""
	}
	fracDigits := len(fracPic) // number of 9's
	absVal := value.Abs()
	// round to fracDigits? MOVE rounds? We'll round half away? but for safety truncate? However COBOL MOVE to edited rounds?
	// Use Round for edited move
	if fracDigits > 0 {
		absVal = absVal.Round(int32(fracDigits))
	}

	// get decimal string with exactly fracDigits
	var intDigitsStr, fracDigitsStr string
	if fracDigits > 0 {
		s := absVal.StringFixed(int32(fracDigits))
		parts := strings.SplitN(s, ".", 2)
		intDigitsStr = parts[0]
		if len(parts) > 1 {
			fracDigitsStr = parts[1]
		} else {
			fracDigitsStr = strings.Repeat("0", fracDigits)
		}
		if len(fracDigitsStr) < fracDigits {
			fracDigitsStr += strings.Repeat("0", fracDigits-len(fracDigitsStr))
		}
	} else {
		intDigitsStr = absVal.Truncate(0).StringFixed(0)
	}

	// handle integer digit capacity truncation (high-order dropped)
	capCount := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			capCount++
		}
	}
	if len(intDigitsStr) > capCount {
		intDigitsStr = intDigitsStr[len(intDigitsStr)-capCount:]
	}

	// build raw integer formatted string
	raw := make([]rune, len(intPic))
	dPos := len(intDigitsStr) - 1
	for i := len(intPic) - 1; i >= 0; i-- {
		ch := intPic[i]
		if ch == ',' || ch == '.' {
			raw[i] = rune(ch)
		} else if ch == 'Z' || ch == '9' {
			if dPos >= 0 {
				raw[i] = rune(intDigitsStr[dPos])
				dPos--
			} else {
				raw[i] = '0'
			}
		} else {
			raw[i] = rune(ch)
		}
	}

	// suppression
	// find indexes of digit positions
	// find first non-zero digit position
	firstNonZero := -1
	for i := 0; i < len(raw); i++ {
		pch := rune(intPic[i])
		if pch == 'Z' || pch == '9' {
			if raw[i] != '0' {
				firstNonZero = i
				break
			}
		}
	}
	if firstNonZero == -1 {
		// find rightmost '9' position
		for i := len(intPic) - 1; i >= 0; i-- {
			if rune(intPic[i]) == '9' {
				firstNonZero = i
				break
			}
		}
		if firstNonZero == -1 {
			// no 9, just keep last digit pos
			for i := len(intPic) - 1; i >= 0; i-- {
				if rune(intPic[i]) == 'Z' || rune(intPic[i]) == '9' {
					firstNonZero = i
					break
				}
			}
		}
	}
	if firstNonZero != -1 {
		for i := 0; i < firstNonZero; i++ {
			pch := rune(intPic[i])
			if pch == 'Z' {
				raw[i] = ' '
			} else if pch == ',' {
				raw[i] = ' '
			}
		}
		// also any Z positions before firstNonZero already handled (including those with zero)
		// commas already handled
	}

	intPartStr := string(raw)
	var result string
	if hasSign {
		result = string(signChar) + intPartStr
	} else {
		result = intPartStr
	}
	if fracDigits > 0 {
		result = result + "." + fracDigitsStr
	}
	// ensure length equals pic length (should already)
	if len(result) < len(pic) {
		result = strings.Repeat(" ", len(pic)-len(result)) + result
	} else if len(result) > len(pic) {
		result = result[len(result)-len(pic):]
	}
	return result
}

func formatWsAmtEd(v decimal.Decimal) string {
	return formatEdited(v, "ZZ,ZZ9.99")
}
func formatWsBalEd(v decimal.Decimal) string {
	return formatEdited(v, "-Z,ZZZ,ZZ9.99")
}
func formatWsTotEd(v decimal.Decimal) string {
	return formatEdited(v, "-ZZZ,ZZZ,ZZ9.99")
}

func formatPIC99(v int64) string {
	// PIC 99 -> width 2 zero padded
	s := fmt.Sprintf("%02d", v%100)
	if len(s) > 2 {
		s = s[len(s)-2:]
	}
	return s
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

// Paragraphs

func ReadPara() {
	if scanner.Scan() {
		line := scanner.Text()
		// pad with spaces on right if shorter than 14
		if len(line) < 14 {
			line = line + strings.Repeat(" ", 14-len(line))
		} else if len(line) > 14 {
			line = line[:14]
		}
		brBranch := line[0:2]
		brAcct := line[2:6]
		brType := line[6:7]
		brAmtStr := line[7:14]
		// parse BrAmt digits only
		brAmtStrTrim := strings.TrimSpace(brAmtStr)
		var amt decimal.Decimal
		if brAmtStrTrim == "" {
			amt = decimal.New(0, 0)
		} else {
			// brAmtStr may contain spaces? Remove them
			clean := strings.TrimSpace(brAmtStr)
			// keep digits only
			// if contains non-digit, treat as 0? But spec says digits
			var digits strings.Builder
			for _, ch := range clean {
				if ch >= '0' && ch <= '9' {
					digits.WriteRune(ch)
				}
			}
			ds := digits.String()
			if ds == "" {
				amt = decimal.New(0, 0)
			} else {
				// parse as integer
				dInt := decimal.RequireFromString(ds)
				amt = decimal.New(dInt.IntPart(), -2)
				// Alternative: use NewFromString with shift
				// But ds may be large, use decimal
				// Use manual: decimal.NewFromString doesn't handle implied
				// So we use integer*10^-2
				// dInt is integer value of 7 digits, need shift -2
				// dInt.IntPart may overflow int64 for 7 digits? max 9,999,999 fits
				// Use decimal
				val, _ := decimal.NewFromString(ds)
				amt = val.Shift(-2)
			}
		}
		curRec = LedgerRec{
			BrBranch: brBranch,
			BrAcct:   brAcct,
			BrType:   brType,
			BrAmt:    amt,
		}
	} else {
		WsEofFlag = "Y"
	}
}

func PostPara() {
	WsAmtEd = formatWsAmtEd(curRec.BrAmt)
	switch curRec.BrType {
	case "D":
		WsBal = storeS9_7V99(WsBal.Add(curRec.BrAmt))
		// DISPLAY BR-ACCT " D " WS-AMT-ED
		fmt.Println(curRec.BrAcct + " D " + WsAmtEd)
	case "C":
		WsBal = storeS9_7V99(WsBal.Sub(curRec.BrAmt))
		fmt.Println(curRec.BrAcct + " C " + WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		fmt.Println(curRec.BrAcct + " ? SKIPPED")
	}
}

func AcctBreakPara() {
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Println("  ACCOUNT " + WsPrevAcct + " BALANCE:" + WsBalEd)
	WsBranchTot = storeS9_9V99(WsBranchTot.Add(WsBal))
	WsBal = decimal.New(0, 0)
}

func BranchBreakPara() {
	WsTotEd = formatWsTotEd(WsBranchTot)
	fmt.Println(" BRANCH " + WsPrevBranch + " TOTAL:" + WsTotEd)
	WsGrandTot = storeS9_9V99(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.New(0, 0)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func GrandPara() {
	WsTotEd = formatWsTotEd(WsGrandTot)
	fmt.Println("GRAND TOTAL:" + WsTotEd)
	fmt.Println("SKIPPED: " + formatPIC99(WsSkipped))
}

func MainPara() {
	// OPEN INPUT LEDGER-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		WsEofFlag = "Y"
		// still need to handle grand
		if !isFirstRecord() {
			AcctBreakPara()
			BranchBreakPara()
		}
		GrandPara()
		return
	}
	ledgerFile = f
	defer f.Close()
	scanner = bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 4096)
	scanner.Buffer(buf, 1024*1024)

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	GrandPara()
}

func main() {
	// initialize working-storage properly
	WsPrevBranch = padRight("", 2)
	WsPrevAcct = padRight("", 4)
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	MainPara()
}

